export const GRADUATE_CATALOG_2022=Object.freeze(ROWS.map(([code,name,mastersOnly])=>Object.freeze({
  code,name,
  categoryCode:code.slice(0,2),
  categoryName:GRADUATE_DISCIPLINE_CATEGORIES_2022[code.slice(0,2)]||'',
  kind:Number(code[2])>=5?'professional_degree_category':'first_level_discipline',
  mastersOnly:Boolean(mastersOnly),
  sourceVersion:GRADUATE_CATALOG_2022_VERSION
})));

const BY_CODE=new Map(GRADUATE_CATALOG_2022.map(item=>[item.code,item]));
const BY_NAME=new Map();
for(const item of GRADUATE_CATALOG_2022){
  const list=BY_NAME.get(item.name)||[];
  list.push(item);
  BY_NAME.set(item.name,list);
}

export function resolveGraduateCatalogEntity(value='',{kind=''}={}){
  const raw=String(value==null?'':value).normalize('NFKC').trim();
  if(!raw)return null;
  const byCode=BY_CODE.get(raw);
  if(byCode&&(!kind||byCode.kind===kind))return{status:'resolved',matchType:'code_exact',item:byCode};
  const candidates=(BY_NAME.get(raw)||[]).filter(item=>!kind||item.kind===kind);
  if(candidates.length===1)return{status:'resolved',matchType:'name_exact',item:candidates[0]};
  if(candidates.length>1)return{status:'ambiguous',matchType:'name_ambiguous',candidates};
  return null;
}

export function graduateCatalogStats(){
  const firstLevel=GRADUATE_CATALOG_2022.filter(item=>item.kind==='first_level_discipline');
  const professional=GRADUATE_CATALOG_2022.filter(item=>item.kind==='professional_degree_category');
  return{
    version:GRADUATE_CATALOG_2022_VERSION,
    categories:Object.keys(GRADUATE_DISCIPLINE_CATEGORIES_2022).length,
    entries:GRADUATE_CATALOG_2022.length,
    firstLevelDisciplines:firstLevel.length,
    professionalDegreeCategories:professional.length,
    mastersOnlyProfessionalDegreeCategories:professional.filter(item=>item.mastersOnly).length
  };
}
